     """# a comment
import sys
"""docstring"""
class MyClass:
    @classmethod
    def cm(cls): pass
    @staticmethod
    def sm(): pass
    async def am(self): pass
    def m(self, x: int):
        with open("a") as f:
            try:
                g = 1
                f = lambda y: y + 1
                foo(x)
            except Exception:
                pass
"""),
    ("rust", ["comments", "doc-comments", "uses", "strings", "attribute", "struct", "priv-struct", "pub-struct", "enum", "enum-variant", "fn", "priv-fn", "pub-fn", "const-fn", "async-fn", "unsafe-fn", "extern-fn", "test-fn", "trait", "impl", "impl-type", "impl-trait", "mod", "type-def", "identifier", "type-identifier", "closure", "unsafe"],
     """// comment
