#[test]
pub struct Foo;
enum Bar { Variant1 }
fn normal() {}
pub fn pubfn() {}
const fn cfn() {}
async fn afn() {}
unsafe fn ufn() {}
extern "C" fn efn() {}
trait MyTrait {}
impl Foo {}
impl MyTrait for Foo {}
mod mymod {}
fn main() {
    let f = |x| x + 1;
    unsafe { }
}
""")
]

for lang, scopes, code in tests:
    for s in scopes:
        cmd = ["./executable", f"--{lang}", s]
        res = subprocess.run(cmd, input=code.encode(), capture_output=True)
        out = res.stdout.decode().strip()
        print(f"[{lang}:{s}] -> {len(out.splitlines())} matches")
        if out:
            print("  " + "\n  ".join(out.splitlines()[:3]))
'"}

