            sys.exit(1)
        if is_search_mode:
            return "", False

    if all_matches and opts["fail_any"]:
        sys.stderr.write("Error: Error applying: Some input was in scope\n")
        sys.exit(1)

    if is_search_mode:
        # Format output in Search Mode: source:line:start_col-end_col:line_content
        out_lines = []
        lines = text.splitlines(keepends=True)
